bash: cd /usr/local/src/klee && python3 - <<'EOF'
import re
p='lib/Solver/STPSolver.cpp'
s=open(p).read()
s=s.replace('enum SAT { MINISAT, SIMPLEMINISAT, CRYPTOMINISAT, RISS };',
            'enum SAT { MINISAT, SIMPLEMINISAT, CRYPTOMINISAT, CADICAL };')
s=s.replace('"CryptoMiniSat", "RISS"};','"CryptoMiniSat", "CadiCaL"};')
s=s.replace('clEnumValN(SAT::RISS, "riss", SATNames[SAT::RISS])),',
            'clEnumValN(SAT::CADICAL, "cadical", SATNames[SAT::CADICAL])),')
s=s.replace('''  case SAT::RISS: {
    SATSolverAvailable = vc_useRiss(vc);
    break;
  }''','''  case SAT::CADICAL: {
    SATSolverAvailable = vc_useCadical(vc);
    break;
  }''')
s=s.replace('''  else if (vc_isUsingRiss(vc))
    SATName = SATNames[SAT::RISS];''','''  else if (vc_isUsingCadical(vc))
    SATName = SATNames[SAT::CADICAL];''')
open(p,'w').write(s)
EOF
grep -n 'CADICAL\|Cadical\|RISS\|Riss' lib/Solver/STPSolver.cpp

