summary:
bash: mkdir -p /tmp/kleetest && cd /tmp/kleetest && cat > test.c <<'EOF'
#include <klee/klee.h>
int get_sign(int x) {
  if (x == 0) return 0;
  if (x < 0) return -1;
  return 1;
}
int main() {
  int a;
  klee_make_symbolic(&a, sizeof(a), "a");
  return get_sign(a);
}
EOF
clang-16 -emit-llvm -c -g -O0 -I/usr/local/include test.c -o test.bc && ls test.bc

